/**
 * The committed test vault (`test-vault/`, regenerated by scripts/make-test-vault.mjs) must stay
 * valid: an engine change that makes its tables, rules or views fail is caught here. The vault is
 * copied to a temporary folder first (tests/helpers/test-vault.ts), so the committed one is never
 * written. Every operation on it: tests/test-vault-ops/.
 */

import { afterAll, beforeAll, describe, expect, it } from "vitest";
import type { DatanotesClient } from "../src/api/client";
import { openTestVault, type TestVault } from "./helpers/test-vault";

let vault: TestVault | undefined;
let db: DatanotesClient;

beforeAll(async () => {
  vault = await openTestVault("service");
  db = vault.client;
}, 30_000);

afterAll(async () => {
  await vault?.stop();
});

const TABLES = ["work.planning.person", "work.planning.project", "work.planning.task"];

describe("test-vault/", () => {
  it("has the expected tables and views", async () => {
    const r = await db.call("describe_database", {});
    expect(r.ok, JSON.stringify(r.value)).toBe(true);
    const text = JSON.stringify(r.value);
    for (const t of ["person", "project", "task", "vw_open_tasks", "vw_engineering"]) expect(text).toContain(`"${t}"`);
    for (const view of ["vw_open_tasks", "vw_engineering"]) {
      const rows = await db.call("select_rows", { table: view });
      expect(rows.ok, JSON.stringify(rows.value)).toBe(true);
      expect((rows.value as { rows: unknown[] }).rows.length).toBeGreaterThan(0);
    }
  });

  it("every table is valid: check_table finds no violations", async () => {
    const all = await db.call("check_table", {});
    expect(all.ok, JSON.stringify(all.value)).toBe(true);
    const v = all.value as { tables_checked: number; rows_checked: number; violations: unknown[] };
    expect(v.violations).toEqual([]);
    expect(v.tables_checked).toBe(TABLES.length);
    expect(v.rows_checked).toBeGreaterThanOrEqual(15);
    for (const table of TABLES) {
      const one = await db.call("check_table", { table });
      expect(one.ok, JSON.stringify(one.value)).toBe(true);
      expect((one.value as { violations: unknown[] }).violations, table).toEqual([]);
    }
  });

  it("enforces its rules: a task on an area and a done task without a date are refused", async () => {
    const onArea = await db.call("insert_row", { table: "work.planning.task", values: { title: "Plan the year", project: "[[Engineering]]" }, dry_run: true });
    expect(onArea.ok).toBe(false);
    expect(JSON.stringify(onArea.value)).toContain("not_on_an_area");
    const noDate = await db.call("insert_row", { table: "work.planning.task", values: { title: "Ship it", project: "[[Website relaunch]]", status: "done" }, dry_run: true });
    expect(noDate.ok).toBe(false);
    expect(JSON.stringify(noDate.value)).toContain("done_has_date");
    const wrongLevel = await db.call("insert_row", { table: "work.planning.project", values: { name: "Hiring", kind: "workstream", parent: "[[Operations]]" }, dry_run: true });
    expect(wrongLevel.ok).toBe(false);
    const fine = await db.call("insert_row", { table: "work.planning.task", values: { title: "Ship it", project: "[[Website relaunch]]" }, dry_run: true });
    expect(fine.ok, JSON.stringify(fine.value)).toBe(true);
  });
});
